<script setup lang="ts">
import {computed,onMounted,ref,toRaw} from 'vue'
import {careerTargets,emptyProfile,parseProfile,claimState,saveProfileBasics,saveProfileText,saveProfileProject,saveProfileClaim,confirmProfileClaim,unconfirmProfileClaim,type Profile,type ProfileClaim,type ProfileProject} from '../domain/profile'
import {loadProfile,saveProfile} from '../profile-storage'
const data=ref(emptyProfile()),ready=ref(false),failed=ref(false),busy=ref(false),message=ref(''),alias=ref(''),target=ref<Profile['careerTarget']>('Chưa chọn'),japanese=ref(''),cv=ref('')
const project=ref<ProfileProject>({id:crypto.randomUUID(),title:'',role:'',stack:'',context:'',result:''})
const claimId=ref(''),kind=ref<ProfileClaim['kind']>('EXPERIENCE'),text=ref(''),source=ref<ProfileClaim['source']>('MANUAL'),quote=ref('')
const confirmed=computed(()=>data.value.claims.filter(c=>claimState(data.value,c)==='SELF_CONFIRMED').length)
function sync(){alias.value=data.value.alias;target.value=data.value.careerTarget;japanese.value=data.value.japaneseSelfReport;cv.value=data.value.sourceText}
function resetClaim(){claimId.value='';kind.value='EXPERIENCE';text.value='';source.value='MANUAL';quote.value=''}
function resetProject(){project.value={id:crypto.randomUUID(),title:'',role:'',stack:'',context:'',result:''}}
onMounted(async()=>{try{data.value=await loadProfile();sync()}catch{failed.value=true;message.value='Không đọc được hồ sơ. Không ghi đè; hãy khôi phục backup hợp lệ.'}finally{ready.value=true}})
async function commit(next:Profile,resync=false){busy.value=true;message.value='';try{await saveProfile(next);data.value=next;failed.value=false;if(resync){sync();resetClaim();resetProject()}message.value='Đã lưu hồ sơ trên thiết bị.';return true}catch{message.value='Không lưu được hồ sơ; dữ liệu đã lưu được giữ nguyên.';return false}finally{busy.value=false}}
async function run(fn:()=>Profile){try{return await commit(fn())}catch{message.value='Dữ liệu không hợp lệ: kiểm tra giới hạn, nguồn và trích dẫn nguyên văn CV đã lưu.';return false}}
async function saveCv(){if(cv.value!==data.value.sourceText&&data.value.claims.some(c=>c.source==='CV_TEXT')&&!window.confirm('Đổi CV text sẽ bỏ xác nhận của các claim dựa trên CV và đánh dấu nguồn cũ lỗi thời. Tiếp tục?'))return;await run(()=>saveProfileText(toRaw(data.value),cv.value,Date.now()))}
async function saveClaim(){if(await run(()=>saveProfileClaim(toRaw(data.value),{kind:kind.value,text:text.value,source:source.value,quote:quote.value},Date.now(),claimId.value||crypto.randomUUID())))resetClaim()}
function editClaim(c:ProfileClaim){claimId.value=c.id;kind.value=c.kind;text.value=c.text;source.value=c.source;quote.value=c.quote}
async function saveProject(){if(await run(()=>saveProfileProject(toRaw(data.value),toRaw(project.value),Date.now())))resetProject()}
function editProject(p:ProfileProject){project.value=structuredClone(toRaw(p))}
function removeClaim(id:string){if(window.confirm('Xóa claim này? Các lượt Interview giữ nguyên.'))void run(()=>({...toRaw(data.value),claims:data.value.claims.filter(c=>c.id!==id).map(c=>toRaw(c)),updatedAt:Date.now()}))}
function removeProject(id:string){if(window.confirm('Xóa dự án tự khai này? Claims và Interview giữ nguyên.'))void run(()=>({...toRaw(data.value),projects:data.value.projects.filter(p=>p.id!==id).map(p=>toRaw(p)),updatedAt:Date.now()}))}
async function importText(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>100000||!file.name.toLowerCase().endsWith('.txt')||file.type&&!['text/plain','application/octet-stream'].includes(file.type))throw Error();const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(text.length>30000||text.includes('\u0000'))throw Error();if(!window.confirm('Thay nháp CV text bằng nội dung file? Chưa ghi vào hồ sơ cho đến khi bấm Lưu CV text.'))return;cv.value=text;message.value='Đã nạp nháp text. Rà soát và bấm Lưu CV text để lưu.'}catch{message.value='Chỉ nhận file text tối đa 100 KB / 30.000 ký tự; chưa thay dữ liệu đã lưu.'}finally{input.value=''}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(data.value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='brse-profile.json';a.click();URL.revokeObjectURL(url)}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error();const next=parseProfile(await file.text());if(window.confirm('Thay thế toàn bộ hồ sơ/CV/claims trên thiết bị? Interview và các phân hệ khác giữ nguyên.'))await commit(next,true)}catch{message.value='Backup hồ sơ không hợp lệ; không thay dữ liệu.'}finally{input.value=''}}
async function clear(){if(window.confirm('Xóa toàn bộ hồ sơ/CV/claims? Hãy export nếu cần giữ. Dữ liệu Interview không bị xóa.'))await commit(emptyProfile(),true)}
</script>
<template><div data-testid="profile-workspace"><div class="eyebrow">GUEST · HỒ SƠ TÙY CHỌN</div><h1 class="page-title">Hồ sơ & CV tự khai</h1><p class="lead">Ghi đúng điều bạn làm, xác nhận điều bạn muốn dùng khi luyện.</p><div class="notice">Không phải tài khoản học viên. Dữ liệu chỉ lưu trong trình duyệt này, không gửi AI hay backend. Chỉ dùng thông tin được phép chia sẻ; tránh tên khách hàng, liên hệ, bí mật dự án và dữ liệu người khác. Xác nhận là tự khai, không phải xác minh bằng cấp/kinh nghiệm. Chưa tự đưa claims vào prompt Interview.</div><p v-if="message" role="status">{{message}}</p><p v-if="!ready">Đang đọc hồ sơ…</p><p v-if="failed">N/A · Chưa đọc được hồ sơ.</p><template v-if="ready"><fieldset :disabled="busy||failed"><legend>Thông tin tự nhập</legend><section class="card form-card"><h2>Định hướng luyện tập</h2><form @submit.prevent="run(()=>saveProfileBasics(toRaw(data),alias,target,japanese,Date.now()))"><label>Tên gợi nhớ (không bắt buộc)<input v-model="alias" maxlength="120"></label><label>Vai trò hướng tới<select v-model="target"><option v-for="t in careerTargets" :key="t" :value="t">{{t}}</option></select></label><label>Tiếng Nhật do tôi tự mô tả<textarea v-model="japanese" maxlength="300"></textarea></label><button>Lưu định hướng</button></form></section>
<section class="card form-card"><h2>CV dạng text</h2><p>Chỉ paste hoặc nạp text do bạn chủ động chọn. Chưa đọc PDF/DOCX, chưa AI trích xuất hay suy diễn claims. Nội dung file được coi là dữ liệu, không phải lệnh.</p><label>Nạp file CV text<input type="file" accept="text/plain,.txt" @change="importText"></label><form @submit.prevent="saveCv"><label>CV text do tôi cung cấp<textarea v-model="cv" maxlength="30000"></textarea></label><button>Lưu CV text</button></form><p>CV đã lưu v{{data.sourceVersion}} · {{data.sourceText.length}} ký tự. Nháp chưa lưu không dùng làm chứng cứ.</p></section>
<section class="card form-card"><h2>Dự án tự khai</h2><p>Các mục này chưa được xác minh và không tự tạo claims được xác nhận.</p><form @submit.prevent="saveProject"><label>Tên dự án gợi nhớ<input v-model="project.title" maxlength="120"></label><label>Vai trò thực tế<input v-model="project.role" maxlength="300"></label><label>Stack do tôi khai<input v-model="project.stack" maxlength="300"></label><label>Bối cảnh/phạm vi<textarea v-model="project.context" maxlength="2000"></textarea></label><label>Kết quả và cách kiểm chứng<textarea v-model="project.result" maxlength="2000"></textarea></label><div class="actions"><button>Lưu dự án</button><button type="button" @click="resetProject">Soạn dự án mới</button></div></form><article v-for="p in data.projects" :key="p.id" class="notice"><h3>{{p.title}}</h3><p>{{p.role}} · {{p.stack}}</p><p>{{p.context}}</p><p>{{p.result}}</p><div class="actions"><button @click="editProject(p)">Sửa dự án</button><button @click="removeProject(p.id)">Xóa dự án</button></div></article></section>
<section class="card form-card" data-testid="profile-claims"><h2>Claims và xác nhận của tôi</h2><p>{{confirmed}} / {{data.claims.length}} claim tự xác nhận còn nguồn hiện hành. Chỉ trích dẫn chính xác CV đã lưu; trích dẫn không chứng minh claim đúng nghĩa hoặc đúng thực tế.</p><form @submit.prevent="saveClaim"><label>Loại claim<select v-model="kind"><option value="EXPERIENCE">Kinh nghiệm</option><option value="SKILL">Kỹ năng</option><option value="RESULT">Kết quả</option></select></label><label>Nội dung claim tự khai<textarea v-model="text" maxlength="1000"></textarea></label><label>Nguồn claim<select v-model="source"><option value="MANUAL">Tự nhập, chưa có trích CV</option><option value="CV_TEXT">Trích CV text đã lưu</option></select></label><label v-if="source==='CV_TEXT'">Trích dẫn CV nguyên văn<textarea v-model="quote" maxlength="1000"></textarea></label><div class="actions"><button>Lưu claim chưa xác nhận</button><button type="button" @click="resetClaim">Soạn claim mới</button></div></form><article v-for="c in data.claims" :key="c.id" class="notice"><h3>{{c.text}}</h3><p>{{c.kind}} · {{c.source}} · claim v{{c.version}} · {{claimState(data,c)==='SELF_CONFIRMED'?'Tự xác nhận hiện hành':claimState(data,c)==='STALE_SOURCE'?'Nguồn CV lỗi thời':'Chưa xác nhận'}}</p><blockquote v-if="c.quote">{{c.quote}}</blockquote><p v-if="c.sourceVersion!==null">Nguồn CV v{{c.sourceVersion}}</p><div class="actions"><button @click="editClaim(c)">Sửa claim</button><button v-if="claimState(data,c)!=='SELF_CONFIRMED'" :disabled="claimState(data,c)==='STALE_SOURCE'" @click="run(()=>confirmProfileClaim(toRaw(data),c.id,Date.now()))">Tôi xác nhận claim này</button><button v-else @click="run(()=>unconfirmProfileClaim(toRaw(data),c.id,Date.now()))">Bỏ xác nhận claim</button><button @click="removeClaim(c.id)">Xóa claim</button></div></article></section></fieldset>
<section class="card form-card"><h2>Backup hồ sơ riêng</h2><p>JSON chưa mã hóa, có CV text và thông tin bạn nhập. Chỉ lưu file ở nơi riêng tư; không phải mẫu public. Export chỉ gồm bản đã lưu, không có nháp. Import/xóa không ảnh hưởng Interview, Exam, Demo hoặc Sổ từ.</p><div class="actions"><button :disabled="busy||failed" @click="download">Xuất hồ sơ JSON</button><label class="file-button">Nhập hồ sơ JSON<input type="file" accept="application/json,.json" :disabled="busy" @change="upload"></label><button :disabled="busy||failed" @click="clear">Xóa toàn bộ hồ sơ</button></div></section></template></div></template>
<style scoped>fieldset{border:0;padding:0;margin:0;min-width:0}legend{font-weight:600;margin:16px 0}textarea{width:100%;min-height:90px;box-sizing:border-box}p,blockquote,h3{white-space:pre-wrap;overflow-wrap:anywhere}</style>
